def eqcounter(nodes):
    nn = nodes.shape[0]
    IBC = np.zeros([nn, 1], dtype=int)
    neq = 0
    for i in range(nn):
        IBC[i] = int(nodes[i, 2])
        if IBC[i] == 0:
            IBC[i] = neq
            neq = neq + 1
    return neq, IBC

